const D = { energy:.5, cells:.5, hue:300, pattern:.4, shine:.5, x:.5, y:.42, scale:1, speed:1, density:.5, style:'disco', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext;
const hor=H*(0.28+(P.y-0.5)*0.3);
const kick=K.pulse*0.3+A.bass*0.4;
const NX=Math.floor(7+P.cells*11), NZ=Math.floor(9+P.cells*13);

// palette function per style
function cellColor(cx,cz,lit){
  let h,s,b;
  if(sty==='neon'){ h=(P.hue+ (cx*30+cz*12))%360; s=90; b= lit? 100 : 30; }
  else if(sty==='mono'){ h=P.hue; s=8; b= lit? 92 : 22; }
  else if(sty==='arcade'){ h=[0,45,140,210,300][(cx+cz)%5]; s=85; b= lit? 100 : 28; }
  else if(sty==='rainbow'){ h=((cx+cz)*24+t*20)%360; s=80; b= lit? 100 : 35; }
  else { h=(cx%2^cz%2)? (P.hue)%360 : (P.hue+180)%360; s=70; b= lit? 96 : 34; } // disco 2-color
  return color(h,s,b, (60+lit*40)*P.alpha/100);
}
// project a floor point (fx in -1..1, fz 0..1 near..far) to screen
function proj(fx,fz){ const zz=0.15+fz*3.2; const sy=hor + (H-hor)*(1/(1+zz*0.9)); const sx=W*0.5 + fx*W*0.62*(1/(1+zz*0.5)); return [sx,sy]; }

// dark upper (club wall) with faint glow
noStroke(); let g=dc.createLinearGradient(0,0,0,hor); g.addColorStop(0,color(P.hue,40,6).toString()); g.addColorStop(1,color(P.hue,40,12).toString()); dc.fillStyle=g; rect(0,0,W,hor+1);

// draw floor cells far->near
for(let zi=NZ-1; zi>=0; zi--){ const fz0=zi/NZ, fz1=(zi+1)/NZ;
  for(let xi=0; xi<NX; xi++){ const fx0=(xi/NX-0.5)*2, fx1=((xi+1)/NX-0.5)*2;
    const phase = t*(0.5+en)*P.speed;
    // lighting pattern: diagonal chase / checker pulse / random twinkle
    let lit;
    const pat=P.pattern;
    if(pat<0.33) lit = 0.5+0.5*Math.sin(phase + (xi+zi)*0.6);           // diagonal wave
    else if(pat<0.66) lit = ((xi+zi + Math.floor(phase))%2===0)?1:0.2;   // checker flip (slow)
    else lit = fr(xi*7+zi*13 + Math.floor(phase*1.5)*3);                  // twinkle
    lit = Math.max(0, Math.min(1, lit))*(0.7+kick*0.5);
    const [ax,ay]=proj(fx0,fz0),[bx,by]=proj(fx1,fz0),[ccx,ccy]=proj(fx1,fz1),[ddx,ddy]=proj(fx0,fz1);
    fill(cellColor(xi,zi,lit)); noStroke();
    quad(ax,ay,bx,by,ccx,ccy,ddx,ddy);
    // grout glow
    if(lit>0.6 && sty!=='mono'){ noFill(); stroke(color(P.hue,60,100, lit*40*P.alpha/100)); strokeWeight(1); quad(ax,ay,bx,by,ccx,ccy,ddx,ddy); noStroke(); }
  }
}
// specular sheen sweeping across
if(P.shine>0.05){ dc.save(); blendMode(SCREEN); const shx=W*(0.5+Math.sin(t*0.4)*0.5);
  const rg=dc.createRadialGradient(shx,hor+H*0.2,4,shx,hor+H*0.2,W*0.35); rg.addColorStop(0,color(0,0,100,30*P.shine*P.alpha/100).toString()); rg.addColorStop(1,color(0,0,100,0).toString()); dc.fillStyle=rg; rect(0,hor,W,H-hor); dc.restore(); }
blendMode(BLEND);
